<?php

namespace App\Http\Controllers;

use App\Domain\Administration\AdminAudit;
use App\Domain\Administration\Modules;
use App\Domain\Administration\NumberSequence;
use App\Models\Organization;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\Rule;

class ProcurementController extends Controller
{
    private function enabled(): void { abort_unless(app(Modules::class)->enabled('procurement'), 404); }
    private function allows(Request $request, string $permission): bool { return $request->user()->isSuperAdmin() || $request->user()->can($permission); }
    private function requirePermission(Request $request, string $permission): void { abort_unless($this->allows($request, $permission), 403); }
    private function organization(Request $request): Organization
    {
        $id = (int) ($request->user()->active_organization_id ?: $request->user()->organizations()->orderBy('organizations.name')->value('organizations.id'));
        abort_unless($id && $request->user()->canAccessOrganization($id), 403);
        $organization = Organization::findOrFail($id);
        abort_unless($organization->is_active || $request->user()->isSuperAdmin(), 403);
        return $organization;
    }

    public function index(Request $request)
    {
        $this->enabled();
        abort_unless($this->allows($request, 'procurement.view') || $this->allows($request, 'procurement.requests.create') || $this->allows($request, 'procurement.inventory.manage') || $this->allows($request, 'procurement.assets.manage'), 403);
        $org = $this->organization($request);
        $suppliers = DB::table('procurement_suppliers')->where('organization_id', $org->id)->orderBy('name')->get();
        $requests = DB::table('procurement_requests as r')->leftJoin('users as u', 'u.id', '=', 'r.requested_by')->where('r.organization_id', $org->id)->select('r.*', 'u.name as requester_name')->orderByDesc('r.created_at')->limit(100)->get();
        $orders = DB::table('procurement_purchase_orders as p')->join('procurement_suppliers as s', 's.id', '=', 'p.supplier_id')->where('p.organization_id', $org->id)->select('p.*', 's.name as supplier_name')->orderByDesc('p.ordered_on')->limit(100)->get();
        foreach ($orders as $order) $order->lines = DB::table('procurement_purchase_order_lines')->where('purchase_order_id', $order->id)->get();
        $items = DB::table('procurement_stock_items')->where('organization_id', $org->id)->where('is_active', true)->orderBy('name')->get();
        $locations = DB::table('procurement_stock_locations')->where('organization_id', $org->id)->where('is_active', true)->orderBy('name')->get();
        $balances = DB::table('procurement_stock_balances as b')->join('procurement_stock_items as i', 'i.id', '=', 'b.stock_item_id')->join('procurement_stock_locations as l', 'l.id', '=', 'b.location_id')->where('b.organization_id', $org->id)->select('b.*', 'i.sku', 'i.name as item_name', 'i.unit', 'i.reorder_level', 'l.name as location_name')->orderBy('i.name')->orderBy('l.name')->get();
        $assets = DB::table('procurement_assets as a')->leftJoin('users as u', 'u.id', '=', 'a.assigned_to')->where('a.organization_id', $org->id)->select('a.*', 'u.name as assignee_name')->orderBy('a.name')->limit(150)->get();
        $maintenance = DB::table('procurement_asset_maintenance as m')->join('procurement_assets as a', 'a.id', '=', 'm.asset_id')->where('a.organization_id', $org->id)->select('m.*', 'a.asset_tag', 'a.name as asset_name')->orderByRaw('m.completed_on is null desc')->orderBy('m.scheduled_on')->limit(100)->get();
        $disposals = DB::table('procurement_asset_disposals as d')->join('procurement_assets as a', 'a.id', '=', 'd.asset_id')->where('a.organization_id', $org->id)->select('d.*', 'a.asset_tag', 'a.name as asset_name')->orderByDesc('d.created_at')->limit(100)->get();
        $movements = DB::table('procurement_stock_movements as m')->join('procurement_stock_items as i', 'i.id', '=', 'm.stock_item_id')->leftJoin('procurement_stock_locations as f', 'f.id', '=', 'm.from_location_id')->leftJoin('procurement_stock_locations as t', 't.id', '=', 'm.to_location_id')->where('m.organization_id', $org->id)->select('m.*','i.sku','i.name as item_name','f.name as from_name','t.name as to_name')->orderByDesc('m.created_at')->limit(100)->get();
        $users = $org->users()->orderBy('name')->get(['users.id', 'users.name']);
        $stats = [
            'pending_requests' => DB::table('procurement_requests')->where('organization_id', $org->id)->where('status', 'pending_approval')->count(),
            'open_orders' => DB::table('procurement_purchase_orders')->where('organization_id', $org->id)->whereIn('status', ['issued', 'part_received'])->count(),
            'low_stock' => $balances->filter(fn ($b) => (float) $b->quantity <= (float) $b->reorder_level)->count(),
            'active_assets' => DB::table('procurement_assets')->where('organization_id', $org->id)->whereNotIn('status', ['disposed'])->count(),
        ];
        $spend = DB::table('procurement_purchase_orders')->where('organization_id',$org->id)->whereNotIn('status',['cancelled'])->selectRaw('currency, sum(total) as total')->groupBy('currency')->orderBy('currency')->get();
        return view('procurement.index', compact('org', 'suppliers', 'requests', 'orders', 'items', 'locations', 'balances', 'assets', 'maintenance', 'disposals', 'movements', 'users', 'stats', 'spend'));
    }

    public function supplierStore(Request $request)
    {
        $this->enabled(); $this->requirePermission($request, 'procurement.suppliers.manage'); $org = $this->organization($request);
        $d = $request->validate(['name' => ['required','string','max:180'], 'email' => ['nullable','email','max:180'], 'phone' => ['nullable','string','max:50'], 'address' => ['nullable','string','max:3000'], 'tax_number' => ['nullable','string','max:80'], 'due_diligence_notes' => ['nullable','string','max:5000']]);
        $id = DB::transaction(function () use ($d, $org, $request) { return DB::table('procurement_suppliers')->insertGetId($d + ['organization_id'=>$org->id,'code'=>app(NumberSequence::class)->next('supplier'),'status'=>'active','created_by'=>$request->user()->id,'created_at'=>now(),'updated_at'=>now()]); });
        AdminAudit::record('procurement.supplier.created', 'procurement_suppliers', $id, null, ['name'=>$d['name']], $org->id);
        return back()->with('success', 'Supplier registered.');
    }

    public function requestStore(Request $request)
    {
        $this->enabled(); $this->requirePermission($request, 'procurement.requests.create'); $org = $this->organization($request);
        $d = $request->validate(['title'=>['required','string','max:180'],'description'=>['nullable','string','max:5000'],'department_name'=>['nullable','string','max:120'],'needed_by'=>['nullable','date','after_or_equal:today'],'currency'=>['required','regex:/^[A-Z]{3}$/'],'estimated_total'=>['required','numeric','gt:0','max:100000000000']]);
        $id = DB::transaction(function () use ($d,$org,$request) { $id=DB::table('procurement_requests')->insertGetId($d+['organization_id'=>$org->id,'reference'=>app(NumberSequence::class)->next('purchase_request'),'status'=>'pending_approval','requested_by'=>$request->user()->id,'created_at'=>now(),'updated_at'=>now()]); DB::table('procurement_request_approvals')->insert(['request_id'=>$id,'requested_by'=>$request->user()->id,'status'=>'pending','created_at'=>now(),'updated_at'=>now()]); return $id; });
        AdminAudit::record('procurement.request.submitted','procurement_requests',$id,null,['estimated_total'=>$d['estimated_total']],$org->id);
        return back()->with('success','Purchase request sent for approval.');
    }

    public function requestDecision(Request $request, int $purchaseRequest)
    {
        $this->enabled(); $this->requirePermission($request,'procurement.requests.approve'); $org=$this->organization($request);
        $d=$request->validate(['decision'=>['required',Rule::in(['approved','rejected'])],'decision_note'=>['nullable','string','max:2000']]);
        $record=DB::table('procurement_requests')->where('organization_id',$org->id)->where('id',$purchaseRequest)->first() ?: abort(404);
        abort_unless($record->status==='pending_approval',422); abort_if((int)$record->requested_by===(int)$request->user()->id,403,'You cannot approve your own request.');
        DB::transaction(function()use($d,$record,$request){DB::table('procurement_requests')->where('id',$record->id)->update(['status'=>$d['decision'],'decision_note'=>$d['decision_note']??null,'decided_by'=>$request->user()->id,'decided_at'=>now(),'updated_at'=>now()]);DB::table('procurement_request_approvals')->where('request_id',$record->id)->where('status','pending')->update(['status'=>$d['decision'],'decision_note'=>$d['decision_note']??null,'decided_by'=>$request->user()->id,'decided_at'=>now(),'updated_at'=>now()]);});
        AdminAudit::record('procurement.request.'.$d['decision'],'procurement_requests',$record->id,['status'=>'pending_approval'],['status'=>$d['decision']],$org->id);
        return back()->with('success','Purchase request decision recorded.');
    }

    public function orderStore(Request $request)
    {
        $this->enabled(); $this->requirePermission($request,'procurement.orders.manage'); $org=$this->organization($request);
        $d=$request->validate(['request_id'=>['required','integer'],'supplier_id'=>['required','integer'],'ordered_on'=>['required','date'],'expected_on'=>['nullable','date','after_or_equal:ordered_on'],'currency'=>['required','regex:/^[A-Z]{3}$/'],'lines'=>['required','array','min:1','max:100'],'lines.*.description'=>['required','string','max:240'],'lines.*.stock_item_id'=>['nullable','integer'],'lines.*.quantity'=>['required','numeric','gt:0','max:100000000'],'lines.*.unit_price'=>['required','numeric','min:0','max:100000000000']]);
        $pr=DB::table('procurement_requests')->where('organization_id',$org->id)->where('id',$d['request_id'])->first()?:abort(404);abort_unless($pr->status==='approved',422,'Only approved requests can become purchase orders.');abort_unless(DB::table('procurement_suppliers')->where('organization_id',$org->id)->where('id',$d['supplier_id'])->where('status','active')->exists(),422);
        foreach($d['lines'] as $line)if(!empty($line['stock_item_id']))abort_unless(DB::table('procurement_stock_items')->where('organization_id',$org->id)->where('id',$line['stock_item_id'])->exists(),422);
        $id=DB::transaction(function()use($d,$org,$request,$pr){$total=collect($d['lines'])->sum(fn($l)=>(float)$l['quantity']*(float)$l['unit_price']);$id=DB::table('procurement_purchase_orders')->insertGetId(['organization_id'=>$org->id,'request_id'=>$pr->id,'supplier_id'=>$d['supplier_id'],'reference'=>app(NumberSequence::class)->next('purchase_order'),'currency'=>$d['currency'],'total'=>$total,'status'=>'issued','ordered_on'=>$d['ordered_on'],'expected_on'=>$d['expected_on']??null,'created_by'=>$request->user()->id,'created_at'=>now(),'updated_at'=>now()]);foreach($d['lines'] as $line){$qty=(float)$line['quantity'];$price=(float)$line['unit_price'];DB::table('procurement_purchase_order_lines')->insert(['purchase_order_id'=>$id,'stock_item_id'=>$line['stock_item_id']??null,'description'=>$line['description'],'quantity'=>$qty,'unit_price'=>$price,'received_quantity'=>0,'line_total'=>$qty*$price,'created_at'=>now(),'updated_at'=>now()]);}return$id;});
        AdminAudit::record('procurement.purchase_order.issued','procurement_purchase_orders',$id,null,['request_id'=>$pr->id,'total'=>$total],$org->id);
        return back()->with('success','Purchase order issued.');
    }

    public function receiptStore(Request $request, int $order)
    {
        $this->enabled();$this->requirePermission($request,'procurement.receipts.manage');$org=$this->organization($request);$d=$request->validate(['received_on'=>['required','date'],'notes'=>['nullable','string','max:3000'],'lines'=>['required','array','min:1'],'lines.*.purchase_order_line_id'=>['required','integer'],'lines.*.quantity'=>['required','numeric','gt:0','max:100000000'],'lines.*.location_id'=>['nullable','integer'],'lines.*.discrepancy_note'=>['nullable','string','max:500']]);
        $po=DB::table('procurement_purchase_orders')->where('organization_id',$org->id)->where('id',$order)->first()?:abort(404);abort_if($po->status==='received',422,'This order is fully received.');foreach($d['lines'] as $l){$line=DB::table('procurement_purchase_order_lines')->where('purchase_order_id',$po->id)->where('id',$l['purchase_order_line_id'])->first()?:abort(422);abort_if((float)$l['quantity']>(float)$line->quantity-(float)$line->received_quantity,422,'Receipt quantity exceeds the outstanding order quantity.');if($line->stock_item_id){abort_unless(!empty($l['location_id'])&&DB::table('procurement_stock_locations')->where('organization_id',$org->id)->where('id',$l['location_id'])->where('is_active',true)->exists(),422,'Choose an active stock location for stocked goods.');}}
        DB::transaction(function()use($d,$po,$org,$request){DB::table('procurement_purchase_orders')->where('id',$po->id)->lockForUpdate()->first();$receipt=DB::table('procurement_goods_receipts')->insertGetId(['organization_id'=>$org->id,'purchase_order_id'=>$po->id,'reference'=>app(NumberSequence::class)->next('goods_receipt'),'received_on'=>$d['received_on'],'notes'=>$d['notes']??null,'received_by'=>$request->user()->id,'created_at'=>now(),'updated_at'=>now()]);foreach($d['lines'] as $l){$line=DB::table('procurement_purchase_order_lines')->where('purchase_order_id',$po->id)->where('id',$l['purchase_order_line_id'])->lockForUpdate()->first();abort_unless($line,422,'Purchase order line not found.');$qty=(float)$l['quantity'];abort_if($qty>(float)$line->quantity-(float)$line->received_quantity,422,'Receipt quantity exceeds the outstanding order quantity.');DB::table('procurement_goods_receipt_lines')->insert(['receipt_id'=>$receipt,'purchase_order_line_id'=>$line->id,'location_id'=>$l['location_id']??null,'quantity'=>$qty,'discrepancy_note'=>$l['discrepancy_note']??null,'created_at'=>now(),'updated_at'=>now()]);DB::table('procurement_purchase_order_lines')->where('id',$line->id)->update(['received_quantity'=>(float)$line->received_quantity+$qty,'updated_at'=>now()]);if($line->stock_item_id)$this->changeBalance($org->id,$line->stock_item_id,(int)$l['location_id'],$qty,'receipt',null,$po->reference,$request->user()->id);}$pending=DB::table('procurement_purchase_order_lines')->where('purchase_order_id',$po->id)->whereRaw('received_quantity < quantity')->exists();DB::table('procurement_purchase_orders')->where('id',$po->id)->update(['status'=>$pending?'part_received':'received','updated_at'=>now()]);});
        AdminAudit::record('procurement.goods_received','procurement_purchase_orders',$po->id,null,['receipt_lines'=>count($d['lines'])],$org->id);return back()->with('success','Goods receipt saved; stock balances updated for inventory lines.');
    }

    public function itemStore(Request $request){$this->enabled();$this->requirePermission($request,'procurement.inventory.manage');$org=$this->organization($request);$d=$request->validate(['sku'=>['required','alpha_dash','max:60',Rule::unique('procurement_stock_items')->where('organization_id',$org->id)],'name'=>['required','string','max:180'],'category'=>['nullable','string','max:100'],'unit'=>['required','string','max:30'],'reorder_level'=>['required','numeric','min:0','max:1000000000']]);DB::table('procurement_stock_items')->insert($d+['organization_id'=>$org->id,'is_active'=>true,'created_by'=>$request->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Stock item created.');}
    public function locationStore(Request $request){$this->enabled();$this->requirePermission($request,'procurement.inventory.manage');$org=$this->organization($request);$d=$request->validate(['code'=>['required','alpha_dash','max:40',Rule::unique('procurement_stock_locations')->where('organization_id',$org->id)],'name'=>['required','string','max:140'],'description'=>['nullable','string','max:250']]);DB::table('procurement_stock_locations')->insert($d+['organization_id'=>$org->id,'is_active'=>true,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Stock location created.');}

    public function movementStore(Request $request)
    {
        $this->enabled();$this->requirePermission($request,'procurement.inventory.manage');$org=$this->organization($request);$d=$request->validate(['stock_item_id'=>['required','integer'],'movement_type'=>['required',Rule::in(['adjustment','transfer'])],'from_location_id'=>['nullable','integer'],'to_location_id'=>['nullable','integer'],'quantity'=>['required','numeric','gt:0','max:100000000'],'reference'=>['nullable','string','max:100'],'notes'=>['nullable','string','max:3000']]);abort_unless(DB::table('procurement_stock_items')->where('organization_id',$org->id)->where('id',$d['stock_item_id'])->exists(),422);$from=$d['from_location_id']??null;$to=$d['to_location_id']??null;
        DB::transaction(function()use($d,$org,$request,$from,$to){if($d['movement_type']==='transfer'){abort_unless($from&&$to&&$from!==$to,422,'Select different source and destination locations.');$this->validLocation($org->id,$from);$this->validLocation($org->id,$to);$this->changeBalance($org->id,$d['stock_item_id'],$from,-(float)$d['quantity'],'transfer',$to,$d['reference']??null,$request->user()->id,$d['notes']??null);$this->changeBalance($org->id,$d['stock_item_id'],$to,(float)$d['quantity'],'transfer',$from,$d['reference']??null,$request->user()->id,$d['notes']??null);}else{abort_unless(($from xor $to),422,'Choose exactly one location for an adjustment.');$location=$from?:$to;$this->validLocation($org->id,$location);$delta=$to?(float)$d['quantity']:-(float)$d['quantity'];$this->changeBalance($org->id,$d['stock_item_id'],$location,$delta,'adjustment',null,$d['reference']??null,$request->user()->id,$d['notes']??null);}});
        return back()->with('success','Stock movement recorded.');
    }
    private function validLocation(int $orgId,int $location):void{abort_unless(DB::table('procurement_stock_locations')->where('organization_id',$orgId)->where('id',$location)->where('is_active',true)->exists(),422,'Choose a valid active stock location.');}
    private function changeBalance(int $orgId,int $item,int $location,float $delta,string $type,?int $other,?string $reference,?int $user,?string $notes=null):void
    {
        $balance=DB::table('procurement_stock_balances')->where('organization_id',$orgId)->where('stock_item_id',$item)->where('location_id',$location)->lockForUpdate()->first();$current=(float)($balance->quantity??0);abort_if($current+$delta < -0.00001,422,'There is not enough stock at the selected location.');if($balance)DB::table('procurement_stock_balances')->where('id',$balance->id)->update(['quantity'=>$current+$delta,'updated_at'=>now()]);else DB::table('procurement_stock_balances')->insert(['organization_id'=>$orgId,'stock_item_id'=>$item,'location_id'=>$location,'quantity'=>$delta,'created_at'=>now(),'updated_at'=>now()]);DB::table('procurement_stock_movements')->insert(['organization_id'=>$orgId,'stock_item_id'=>$item,'from_location_id'=>$delta<0?$location:$other,'to_location_id'=>$delta>0?$location:$other,'movement_type'=>$type,'quantity'=>abs($delta),'reference'=>$reference,'notes'=>$notes,'created_by'=>$user,'created_at'=>now(),'updated_at'=>now()]);
    }

    public function assetStore(Request $request){$this->enabled();$this->requirePermission($request,'procurement.assets.manage');$org=$this->organization($request);$d=$request->validate(['name'=>['required','string','max:180'],'category'=>['nullable','string','max:100'],'serial_number'=>['nullable','string','max:120'],'acquired_on'=>['nullable','date'],'purchase_cost'=>['nullable','numeric','min:0','max:100000000000'],'currency'=>['required','regex:/^[A-Z]{3}$/'],'location'=>['nullable','string','max:160'],'assigned_to'=>['nullable','integer'],'notes'=>['nullable','string','max:3000']]);if(!empty($d['assigned_to']))abort_unless($org->users()->where('users.id',$d['assigned_to'])->exists(),422);$id=DB::transaction(fn()=>DB::table('procurement_assets')->insertGetId($d+['organization_id'=>$org->id,'asset_tag'=>app(NumberSequence::class)->next('asset'),'status'=>empty($d['assigned_to'])?'available':'assigned','created_by'=>$request->user()->id,'created_at'=>now(),'updated_at'=>now()]));AdminAudit::record('procurement.asset.registered','procurement_assets',$id,null,['name'=>$d['name']],$org->id);return back()->with('success','Asset registered.');}
    public function assetUpdate(Request $request,int $asset){$this->enabled();$this->requirePermission($request,'procurement.assets.manage');$org=$this->organization($request);$a=DB::table('procurement_assets')->where('organization_id',$org->id)->where('id',$asset)->first()?:abort(404);abort_if($a->status==='disposed',422);$d=$request->validate(['assigned_to'=>['nullable','integer'],'location'=>['nullable','string','max:160'],'status'=>['required',Rule::in(['available','assigned','in_maintenance','retired'])],'notes'=>['nullable','string','max:3000']]);if($d['assigned_to']??null)abort_unless($org->users()->where('users.id',$d['assigned_to'])->exists(),422);DB::table('procurement_assets')->where('id',$asset)->update($d+['updated_at'=>now()]);AdminAudit::record('procurement.asset.custody_updated','procurement_assets',$asset,null,$d,$org->id);return back()->with('success','Asset custody and status updated.');}
    public function maintenanceStore(Request $request,int $asset){$this->enabled();$this->requirePermission($request,'procurement.assets.manage');$org=$this->organization($request);$a=DB::table('procurement_assets')->where('organization_id',$org->id)->where('id',$asset)->first()?:abort(404);abort_if($a->status==='disposed',422);$d=$request->validate(['description'=>['required','string','max:240'],'scheduled_on'=>['nullable','date'],'cost'=>['nullable','numeric','min:0','max:100000000000'],'notes'=>['nullable','string','max:3000']]);DB::transaction(function()use($d,$a,$request){DB::table('procurement_asset_maintenance')->insert($d+['asset_id'=>$a->id,'status'=>'scheduled','created_by'=>$request->user()->id,'created_at'=>now(),'updated_at'=>now()]);DB::table('procurement_assets')->where('id',$a->id)->update(['status'=>'in_maintenance','updated_at'=>now()]);});return back()->with('success','Maintenance scheduled.');}
    public function maintenanceComplete(Request $request,int $maintenance){$this->enabled();$this->requirePermission($request,'procurement.assets.manage');$org=$this->organization($request);$m=DB::table('procurement_asset_maintenance as m')->join('procurement_assets as a','a.id','=','m.asset_id')->where('a.organization_id',$org->id)->where('m.id',$maintenance)->select('m.*','a.id as asset_id','a.assigned_to')->first()?:abort(404);abort_unless($m->status==='scheduled',422);DB::transaction(function()use($m){DB::table('procurement_asset_maintenance')->where('id',$m->id)->update(['status'=>'completed','completed_on'=>today(),'updated_at'=>now()]);DB::table('procurement_assets')->where('id',$m->asset_id)->update(['status'=>$m->assigned_to?'assigned':'available','updated_at'=>now()]);});return back()->with('success','Maintenance marked complete.');}
    public function disposalStore(Request $request,int $asset){$this->enabled();$this->requirePermission($request,'procurement.assets.manage');$org=$this->organization($request);$a=DB::table('procurement_assets')->where('organization_id',$org->id)->where('id',$asset)->first()?:abort(404);abort_if($a->status==='disposed',422);$d=$request->validate(['reason'=>['required','string','max:3000']]);DB::table('procurement_asset_disposals')->insert(['asset_id'=>$a->id,'requested_by'=>$request->user()->id,'status'=>'pending_approval','reason'=>$d['reason'],'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Disposal request sent for approval.');}
    public function disposalDecision(Request $request,int $disposal){$this->enabled();$this->requirePermission($request,'procurement.disposals.approve');$org=$this->organization($request);$d=$request->validate(['decision'=>['required',Rule::in(['approved','rejected'])],'decision_note'=>['nullable','string','max:2000']]);$record=DB::table('procurement_asset_disposals as d')->join('procurement_assets as a','a.id','=','d.asset_id')->where('a.organization_id',$org->id)->where('d.id',$disposal)->select('d.*','a.id as asset_id')->first()?:abort(404);abort_unless($record->status==='pending_approval',422);abort_if((int)$record->requested_by===(int)$request->user()->id,403,'The requester cannot approve their own disposal.');DB::transaction(function()use($record,$d,$request){DB::table('procurement_asset_disposals')->where('id',$record->id)->update(['status'=>$d['decision'],'decision_note'=>$d['decision_note']??null,'decided_by'=>$request->user()->id,'decided_at'=>now(),'updated_at'=>now()]);if($d['decision']==='approved')DB::table('procurement_assets')->where('id',$record->asset_id)->update(['status'=>'disposed','assigned_to'=>null,'updated_at'=>now()]);});AdminAudit::record('procurement.disposal.'.$d['decision'],'procurement_asset_disposals',$record->id,['status'=>'pending_approval'],['status'=>$d['decision']],$org->id);return back()->with('success','Disposal decision recorded.');}
}
